import type { SubjectBank } from '@/types';

export const businessStudiesBank: SubjectBank = {
  short: [
    { question: "What is the difference between a sole trader and a limited company?", answer: "A sole trader is owned and run by one person with unlimited liability — personal assets are at risk. A limited company (Ltd or PLC) is a separate legal entity; shareholders have limited liability and can only lose their investment.", acceptedAnswers: ["sole trader has unlimited liability; limited company has limited liability", "sole trader: one owner, unlimited liability; limited company: separate legal entity, limited liability", "sole trader risks personal assets; Ltd company protects personal assets", "limited company is a separate legal entity; sole trader is not"], marks: 2, hint: "Think about liability and legal structure" },
    { question: "What is meant by 'cash flow'?", answer: "Cash flow is the movement of money into and out of a business. Positive cash flow means more money coming in than going out. Negative cash flow can cause a business to fail even if it is profitable.", acceptedAnswers: ["movement of money in and out of a business", "cash coming in minus cash going out", "inflows and outflows of money in a business", "money flowing into and out of the business over time"], marks: 2, hint: "Money in vs money out over time" },
    { question: "What does 'USP' stand for and what is it?", answer: "USP stands for Unique Selling Point — the feature that makes a product or service different from competitors, giving customers a specific reason to buy it.", acceptedAnswers: ["Unique Selling Point", "unique selling point — what makes the product stand out from competitors", "USP = unique selling point; the feature that differentiates a product", "the feature that makes a product unique / different from competitors"], marks: 1, hint: "What makes your product special?" },
    { question: "State two objectives a business might have other than profit maximisation.", answer: "Any two: market share growth; survival (especially startups); social/ethical objectives; customer satisfaction; sales revenue maximisation; environmental sustainability.", acceptedAnswers: ["market share growth and survival", "customer satisfaction and social responsibility", "survival and sales revenue maximisation", "market share and environmental sustainability"], marks: 2, hint: "Not-for-profit goals a business might pursue" },
    { question: "What is meant by 'unlimited liability'?", answer: "Unlimited liability means the owner is personally responsible for all business debts. If the business cannot pay, the owner's personal assets (home, savings) can be taken to cover losses.", acceptedAnswers: ["owner personally responsible for all business debts", "personal assets at risk if business cannot pay debts", "owner's home and savings can be taken to pay debts", "no protection for personal assets — owner liable for all debts"], marks: 2, hint: "Who is responsible for the debts?" },
    { question: "What is the formula for calculating profit?", answer: "Profit = Total Revenue − Total Costs. Total Revenue = Selling Price × Quantity Sold. Total Costs = Fixed Costs + Variable Costs.", acceptedAnswers: ["Profit = Revenue − Costs", "profit = total revenue minus total costs", "revenue − costs = profit", "total revenue − total costs = profit"], marks: 2, hint: "Revenue minus all costs" },
    { question: "Define 'market research' and give one primary and one secondary method.", answer: "Market research is gathering information about customers and the market to support decisions. Primary: surveys, interviews, focus groups, observation. Secondary: government statistics, trade reports, competitor websites.", acceptedAnswers: ["gathering data about customers/market; primary = surveys; secondary = reports/statistics", "market research collects information; primary methods: surveys, interviews; secondary: existing reports", "primary: focus groups / surveys; secondary: government statistics / trade reports", "collecting info about market; e.g. surveys (primary) and trade reports (secondary)"], marks: 2, hint: "One collected first-hand, one already existing" },
    { question: "What is meant by 'economies of scale'?", answer: "Economies of scale occur when a business grows and the average cost per unit falls. Purchasing economies (bulk discounts), managerial economies (specialist staff), and financial economies (better loan rates) all contribute.", acceptedAnswers: ["as output increases, average cost per unit falls", "larger production leads to lower unit costs", "economies of scale = falling average costs as business grows", "unit costs decrease as production scale increases"], marks: 2, hint: "How does growing larger reduce unit costs?" },
    { question: "What is the difference between 'gross profit' and 'net profit'?", answer: "Gross profit = Revenue − Cost of Sales (direct costs only). Net profit = Gross Profit − Operating Expenses (indirect costs like rent, salaries, marketing). Net profit is what the business actually keeps.", acceptedAnswers: ["gross profit = revenue minus cost of sales; net profit = gross profit minus all other expenses", "gross profit deducts only direct costs; net profit deducts all costs", "gross = revenue − cost of sales; net = gross profit − operating expenses", "net profit is after all costs; gross profit is after only direct costs"], marks: 2, hint: "One deducts only direct costs, the other deducts all costs" },
    { question: "Name three stakeholders of a business and state one interest each has.", answer: "Shareholders: want dividends/share value growth. Employees: want fair pay and job security. Customers: want good quality at fair prices. (Other valid: suppliers, government, local community, managers.)", acceptedAnswers: ["shareholders (dividends), employees (fair pay), customers (quality products)", "shareholders want profit; employees want good wages; customers want value", "employees: job security; shareholders: returns; customers: quality and price", "three from: shareholders, employees, customers, suppliers, government — each with a valid interest"], marks: 3, hint: "Think: who is affected by or can affect the business?" },
    { question: "What is 'penetration pricing'?", answer: "Penetration pricing is setting a low initial price to attract customers and gain market share quickly, then raising prices once established. Used when entering competitive markets.", acceptedAnswers: ["setting a low price initially to gain market share", "low price to attract customers when entering a market", "penetration pricing uses low prices to break into market then raises them", "initial low price strategy to win customers from competitors"], marks: 2, hint: "Low price strategy to break into a market" },
    { question: "State two internal sources of finance for a business.", answer: "Any two: retained profit (reinvesting profits); selling assets; owner's savings/capital injection; reducing working capital.", acceptedAnswers: ["retained profit and selling assets", "owner's savings and retained profit", "reinvested profits and selling unused assets", "retained earnings and asset disposal"], marks: 2, hint: "Sources that come from within the business itself" },
    { question: "What is meant by 'division of labour'?", answer: "Division of labour is breaking a production process into specialised tasks with each worker performing one task repeatedly. It increases efficiency and output but can reduce motivation (monotony).", acceptedAnswers: ["breaking production into specialised tasks with each worker doing one task", "workers each specialise in one part of production to increase efficiency", "splitting work into specialised roles to improve efficiency", "each worker does one repeated task to increase productivity"], marks: 2, hint: "Specialisation in the production process" },
    { question: "Define 'brand' in a marketing context.", answer: "A brand is a distinctive name, logo, symbol or design that identifies a product/company and differentiates it from competitors. It represents the values, reputation and personality of the business.", acceptedAnswers: ["a name, logo or design that identifies and differentiates a product or company", "brand identifies a company and represents its values and reputation", "distinctive identity (name/logo) that differentiates a product from competitors", "brand = identity that sets a product apart from competitors"], marks: 2, hint: "More than just a logo — what does it represent?" },
    { question: "What is meant by 'trade credit' as a source of finance?", answer: "Trade credit allows a business to buy goods or services from suppliers and pay later (typically 30, 60 or 90 days). It is a short-term source of finance that improves cash flow.", acceptedAnswers: ["buying from suppliers now and paying later (e.g. 30/60/90 days)", "a supplier allows payment to be delayed, improving cash flow", "purchasing goods and deferring payment to suppliers", "buying stock on credit — pay supplier after 30/60/90 days"], marks: 2, hint: "Buying now, paying later from suppliers" },
    { question: "What is the difference between 'fixed costs' and 'variable costs'? Give an example of each.", answer: "Fixed costs do not change with output (e.g. rent, insurance, manager salaries). Variable costs change directly with output — more you produce, higher the cost (e.g. raw materials, packaging, piece-rate wages).", acceptedAnswers: ["fixed costs don't change with output (e.g. rent); variable costs change with output (e.g. raw materials)", "fixed: rent/insurance — same regardless of output; variable: materials — change with production", "fixed costs = constant (e.g. rent); variable costs = rise with output (e.g. raw materials)", "fixed don't vary with output; variable costs increase as more is produced"], marks: 2, hint: "Does the cost change when you produce more or less?" },
    { question: "State three key characteristics of a successful entrepreneur.", answer: "Any three: risk-taking (willing to invest despite uncertainty); innovative (creates new ideas or improves existing ones); resilient (persists through setbacks); creative (finds novel solutions); leadership (motivates others); financial awareness; determination.", acceptedAnswers: ["risk-taking, innovative, resilient", "creative, determined, risk-taker", "risk-taking, resilience, leadership", "innovative, resilient, creative"], marks: 3, hint: "What personal qualities make a business founder succeed?" },
    { question: "What is meant by 'start-up costs'? Give two examples.", answer: "Start-up costs are one-off expenses paid before or during the launch of a business. Examples: premises purchase/lease deposit, equipment and machinery, initial stock, website development, legal fees, initial marketing/advertising.", acceptedAnswers: ["one-off costs incurred when setting up a business; e.g. equipment and premises", "costs paid before the business opens: e.g. website, stock, equipment", "initial costs: e.g. machinery purchase and first rent payment", "one-time expenses to launch: e.g. legal fees and initial inventory"], marks: 2, hint: "One-off costs before or during launch — not ongoing" },
    { question: "What is a 'sole trader'? State one advantage and one disadvantage.", answer: "A sole trader is a business owned and run by one individual. Advantage: full control over decisions; keeps all profits. Disadvantage: unlimited liability — personal assets at risk; difficult to raise capital.", acceptedAnswers: ["one person owns and runs the business; advantage: full control; disadvantage: unlimited liability", "sole trader = single owner; pro: keeps all profit; con: unlimited liability", "advantage: simple to set up; disadvantage: unlimited liability and hard to raise finance", "one-person business; benefit = control; drawback = personal assets at risk"], marks: 2, hint: "Think control and liability" },
    { question: "What is a 'partnership' in business?", answer: "A partnership is a business owned by two or more people who share responsibilities, profits, and liabilities. Governed by the Partnership Act 1890. Partners usually have unlimited liability unless it is a limited liability partnership (LLP).", acceptedAnswers: ["a business owned by two or more people sharing profits and liabilities", "two or more owners run the business together, sharing profits and unlimited liability", "partnership = 2+ owners; Partnership Act 1890; usually unlimited liability", "shared ownership between 2+ people; governed by Partnership Act 1890"], marks: 2, hint: "Two or more owners — who bears the liability?" },
    { question: "What is a private limited company (Ltd)? State one advantage.", answer: "A private limited company (Ltd) is a separate legal entity where shares are not sold publicly. Shareholders have limited liability. Advantage: limited liability protects personal assets; OR able to raise capital by selling shares to private investors.", acceptedAnswers: ["a separate legal entity whose shares are not publicly traded; advantage: limited liability", "Ltd = separate legal entity, limited liability; shares sold privately", "shareholders have limited liability; cannot sell shares on stock exchange", "private limited company: separate legal entity; advantage is limited liability"], marks: 2, hint: "Separate legal entity — public or private shares?" },
    { question: "What is a franchise?", answer: "A franchise is a business arrangement where a franchisor grants a franchisee the right to operate a business using its brand, systems and products, in exchange for a fee and royalties. Examples: McDonald's, Subway, Domino's.", acceptedAnswers: ["buying the right to use another business's brand and systems", "franchisor grants franchisee the licence to trade using its brand in return for a fee", "operating a business under an established brand name in exchange for fees", "franchisee pays franchisor for right to use their brand, systems and products"], marks: 2, hint: "Buying the right to use someone else's established brand" },
    { question: "What is a 'social enterprise'?", answer: "A social enterprise is a business that prioritises social, ethical or environmental goals alongside (or instead of) profit. Any profits are reinvested into the social mission. Examples: The Big Issue, Divine Chocolate, Cafédirect.", acceptedAnswers: ["a business that prioritises social or environmental goals; reinvests profits into its mission", "social enterprise: profit goes back to social/community goals, not shareholders", "business with social purpose; profits reinvested rather than paid as dividends", "a not-primarily-for-profit business serving a social mission"], marks: 2, hint: "Profit reinvested for social good, not paid to shareholders" },
    { question: "Define 'market segmentation'.", answer: "Market segmentation divides the total market into groups (segments) of customers with similar characteristics or needs, so a business can target each group with a tailored marketing mix.", acceptedAnswers: ["dividing the market into groups of customers with similar needs", "splitting customers into groups based on shared characteristics for targeted marketing", "market segmentation = grouping customers by age, location, lifestyle or behaviour", "dividing the total market into distinct customer groups to target each effectively"], marks: 2, hint: "Splitting the market into groups of similar customers" },
    { question: "State the four stages of the product life cycle.", answer: "Introduction → Growth → Maturity → Decline. At introduction, sales are low and costs high. Growth sees rapid sales rise. Maturity is the peak — competition increases. Decline sees falling sales; the business may withdraw, rebrand or extend the product.", acceptedAnswers: ["introduction, growth, maturity, decline", "the four stages are: introduction, growth, maturity, decline", "introduction → growth → maturity → decline", "launch, growth, maturity, decline"], marks: 2, hint: "Think of a product's life from launch to end" },
    { question: "What is the Boston Matrix? Name its four categories.", answer: "The Boston Matrix is a portfolio analysis tool plotting products by market share and market growth rate. Four categories: Star (high growth, high share), Cash Cow (low growth, high share), Question Mark (high growth, low share), Dog (low growth, low share).", acceptedAnswers: ["star, cash cow, question mark, dog", "four categories: star (high share high growth), cash cow (high share low growth), question mark (low share high growth), dog (low share low growth)", "Boston Matrix: stars, cash cows, question marks, dogs", "portfolio tool with four quadrants: star, cash cow, question mark, dog"], marks: 2, hint: "Portfolio tool — four quadrants based on market share and growth" },
    { question: "What is 'price skimming'?", answer: "Price skimming sets a high initial price for a new product (often innovative) to maximise revenue from early adopters, then gradually reduces the price to attract more price-sensitive customers.", acceptedAnswers: ["setting a high initial price then lowering it over time", "high price at launch to maximise early revenue; then lower as market widens", "skimming extracts maximum revenue from early adopters with high prices initially", "premium launch price reduced over time to attract wider market"], marks: 2, hint: "High price at launch, then lower — opposite of penetration" },
    { question: "What is 'just-in-time' (JIT) production?", answer: "JIT is a lean production approach where materials and components are ordered and delivered just as they are needed for production — minimising stock holding costs but requiring reliable suppliers.", acceptedAnswers: ["ordering materials only when needed for production, minimising stock holding", "just-in-time: stock arrives exactly when needed, reducing storage costs", "JIT = minimum stock held; materials ordered and used immediately", "production system where parts arrive just as needed — low stock, requires reliable suppliers"], marks: 2, hint: "Stock arrives exactly when needed — no excess inventory" },
    { question: "What is meant by 'quality control'?", answer: "Quality control is a system of checking products (usually by inspecting finished goods) to identify defects before they reach the customer. It is reactive — defects are found and removed after production.", acceptedAnswers: ["checking finished products for defects before they reach customers", "quality control inspects output to remove defective products", "reactive system: inspects goods after production to find and remove faults", "checking products at the end of production to ensure they meet standards"], marks: 2, hint: "Checking products after they are made — reactive, not preventative" },
    { question: "What is meant by 'quality assurance'?", answer: "Quality assurance is a proactive system that builds quality into every stage of the production process, aiming to prevent defects occurring rather than just detecting them at the end.", acceptedAnswers: ["building quality into every stage of production to prevent defects", "proactive approach: quality checked throughout the process, not just at the end", "quality assurance prevents defects at every stage rather than checking at the end", "system embedding quality throughout production — preventing rather than detecting faults"], marks: 2, hint: "Prevention throughout the process — proactive, not reactive" },
    { question: "What does 'contribution per unit' mean?", answer: "Contribution per unit = Selling Price − Variable Cost per unit. It shows how much each unit sold contributes towards paying fixed costs, and then to profit once fixed costs are covered.", acceptedAnswers: ["selling price minus variable cost per unit", "contribution = selling price − variable cost; each unit's share towards covering fixed costs", "amount each unit contributes to fixed costs and profit: selling price minus variable cost", "selling price − variable cost per unit = contribution"], marks: 2, hint: "What's left of the selling price after subtracting variable costs?" },
    { question: "What is a 'cash flow forecast'?", answer: "A cash flow forecast is a financial document predicting the expected cash inflows and outflows over a future period (usually monthly). It helps businesses identify future cash shortfalls so they can arrange finance in advance.", acceptedAnswers: ["a document predicting future cash inflows and outflows", "forecast of money coming in and going out, showing future cash balance", "monthly prediction of cash receipts and payments to identify shortfalls", "financial plan showing expected cash in, cash out, and net cash flow"], marks: 2, hint: "Forward-looking document showing expected money in and out" },
    { question: "What is the difference between 'internal' and 'external' recruitment?", answer: "Internal recruitment fills vacancies from existing employees (promotion, redeployment). It is cheaper and motivating but limits fresh ideas. External recruitment advertises to outside candidates — brings new skills but costs more (advertising, agencies).", acceptedAnswers: ["internal: filling vacancies from current staff; external: recruiting from outside the business", "internal recruitment promotes existing employees; external recruits new staff from outside", "internal = cheaper, motivates staff; external = new talent but higher cost", "internal from within the business; external from outside — each has pros and cons"], marks: 2, hint: "Where does the candidate come from — inside or outside the business?" },
    { question: "Name two methods of on-the-job training.", answer: "Any two: job shadowing (watching an experienced colleague); mentoring; apprenticeship (working while training); coaching; job rotation (moving between roles to build wider skills).", acceptedAnswers: ["job shadowing and mentoring", "coaching and job rotation", "apprenticeship and job shadowing", "mentoring and coaching"], marks: 2, hint: "Training that happens at the workplace while working" },
    { question: "What does Taylor's 'scientific management' theory argue?", answer: "Frederick Taylor argued that workers are motivated primarily by money (economic man). He advocated piece-rate pay (pay per unit produced), standardised methods, close supervision, and clear task allocation to maximise efficiency.", acceptedAnswers: ["workers motivated by money; use piece-rate pay and close supervision for efficiency", "Taylor: economic man; piece-rate pay; standardised methods to maximise output", "scientific management: workers paid per unit produced; money is the main motivator", "piece-rate pay and standardised tasks to motivate through financial rewards"], marks: 2, hint: "Money is the motivator — how does Taylor recommend maximising output?" },
    { question: "What is Maslow's 'Hierarchy of Needs'?", answer: "Maslow's Hierarchy has five levels of needs: 1. Physiological (food, pay); 2. Safety (job security); 3. Social (teamwork); 4. Esteem (recognition, status); 5. Self-actualisation (reaching full potential). Lower needs must be met before higher ones motivate.", acceptedAnswers: ["five levels: physiological, safety, social, esteem, self-actualisation", "Maslow's hierarchy: 1 physiological (pay) 2 safety 3 social 4 esteem 5 self-actualisation", "pyramid of needs: basic (pay) → safety → social → esteem → self-actualisation", "five needs from lowest to highest: physiological, safety, social, esteem, self-actualisation"], marks: 2, hint: "A pyramid of five needs — basic needs must be met first" },
    { question: "What is Herzberg's 'two-factor theory'?", answer: "Herzberg identified: Hygiene factors (pay, conditions, job security) — if absent, workers are dissatisfied, but their presence does not motivate. Motivators (achievement, recognition, responsibility, advancement) — actually drive higher performance.", acceptedAnswers: ["hygiene factors prevent dissatisfaction; motivators drive performance", "hygiene factors (pay, conditions) and motivators (achievement, responsibility)", "Herzberg: two factors — hygiene (prevent dissatisfaction) and motivators (drive performance)", "hygiene factors avoid unhappiness; motivators create positive motivation"], marks: 2, hint: "Two types: one prevents dissatisfaction, the other creates motivation" },
    { question: "What is 'span of control' in an organisational structure?", answer: "Span of control is the number of subordinates directly managed by one manager. A wide span (many subordinates) suits flat structures. A narrow span (few subordinates) suits hierarchical structures with close supervision.", acceptedAnswers: ["number of subordinates a manager directly manages", "span of control = how many people report directly to one manager", "number of employees under one manager's direct supervision", "wide span = many subordinates; narrow span = few subordinates reporting to one manager"], marks: 2, hint: "How many people report directly to one manager?" },
    { question: "What is meant by 'delegation' in management?", answer: "Delegation is passing authority and responsibility for tasks to a subordinate. It develops staff skills and frees managers for strategic decisions, but the manager retains overall accountability.", acceptedAnswers: ["passing authority and responsibility to a subordinate", "giving a subordinate the power to make decisions within an assigned task", "delegation = manager assigns task and authority to employee but retains overall accountability", "passing responsibility for a task downwards in the hierarchy"], marks: 2, hint: "Passing authority down the hierarchy — who remains accountable?" },
    { question: "What is the National Minimum Wage (NMW) and why does it exist?", answer: "The NMW is the minimum hourly rate employers must legally pay workers, set by the government (with separate National Living Wage rates for older workers). It exists to prevent exploitation of low-paid workers and reduce poverty.", acceptedAnswers: ["minimum hourly rate set by law that employers must pay workers", "legal minimum pay rate to prevent exploitation of workers", "government-set minimum wage floor; NLW is the higher rate for workers aged 21+", "minimum hourly wage that employers are legally required to pay"], marks: 2, hint: "Government-set minimum legal pay rate" },
    { question: "What is 'gross profit margin' (GPM)?", answer: "GPM = (Gross Profit ÷ Revenue) × 100. It shows the percentage of revenue remaining after deducting cost of sales. A higher GPM means the business is more efficient at generating profit from sales before overheads.", acceptedAnswers: ["GPM = (gross profit / revenue) x 100", "gross profit margin = gross profit divided by revenue times 100", "(gross profit ÷ revenue) × 100 — percentage of sales kept after direct costs", "GPM = gross profit / sales revenue × 100"], marks: 2, hint: "Gross profit divided by revenue, multiplied by 100" },
    { question: "What is 'return on investment' (ROI)?", answer: "ROI = (Net Profit ÷ Investment) × 100. It measures the profitability of an investment relative to its cost. A higher ROI means a more efficient use of the invested capital.", acceptedAnswers: ["ROI = net profit / investment x 100", "return on investment = net profit divided by cost of investment times 100", "(net profit ÷ investment) × 100", "measures profit generated as a percentage of the investment made"], marks: 2, hint: "Net profit as a percentage of what was invested" },
    { question: "What is 'crowdfunding' as a source of finance?", answer: "Crowdfunding raises money from large numbers of people (usually via online platforms like Kickstarter or Crowdcube), each contributing a small amount. Types: reward-based (backers receive a product/perk), equity-based (backers receive shares).", acceptedAnswers: ["raising small amounts from many people via an online platform", "crowdfunding: many people each contribute a small amount via platforms like Kickstarter", "online funding from large numbers of individuals, e.g. Kickstarter or Crowdcube", "raising finance from many small investors or supporters online"], marks: 2, hint: "Many small contributions via an online platform" },
    { question: "What is 'venture capital'?", answer: "Venture capital is investment provided by specialist firms to high-growth, high-risk startups in exchange for equity (shares). Venture capitalists often also provide business expertise and contacts alongside the funding.", acceptedAnswers: ["investment from specialist firms into high-growth startups in exchange for shares", "venture capital = equity investment in startups from specialist investors", "VC firms invest in risky startups in return for a share of the business", "finance from investors who take an equity stake in promising new businesses"], marks: 2, hint: "Equity funding for high-growth startups from specialist investors" },
    { question: "What is meant by a 'trade barrier'? Give one example.", answer: "A trade barrier restricts the free movement of goods and services between countries. Examples: tariff (tax on imports that raises the price of foreign goods); quota (limit on the quantity of imports allowed); embargo (complete ban on imports from a country).", acceptedAnswers: ["a restriction on international trade; e.g. tariff, quota, or embargo", "tariff (tax on imports), quota (limit on imports), or embargo (ban on trade)", "trade barriers restrict imports; examples: tariffs (import taxes) and quotas (import limits)", "restrictions on imports such as tariffs, quotas, or embargoes"], marks: 2, hint: "Government measures that restrict imports — name one type" },
    { question: "What is the impact of a rising exchange rate on UK exporters?", answer: "A rising (appreciating) pound makes UK exports more expensive for overseas buyers — they must pay more in their own currency. This reduces export competitiveness and can lower export sales volumes.", acceptedAnswers: ["exports become more expensive for foreign buyers, reducing competitiveness", "appreciating pound raises export prices for overseas buyers, reducing demand", "stronger pound makes UK goods pricier abroad — reduces export sales", "rising exchange rate hurts exporters because UK goods cost more in foreign currency"], marks: 2, hint: "Think about what happens to the price foreign customers pay" },
    { question: "What is an 'overdraft' as a source of finance?", answer: "An overdraft allows a business to spend more than the balance in its bank account, up to an agreed limit. It is a flexible short-term source of finance but carries high interest rates.", acceptedAnswers: ["spending more than the bank account balance up to an agreed limit", "overdraft = short-term borrowing from bank when account goes below zero", "bank allows business to go into negative balance up to a limit — short-term finance", "flexible short-term borrowing where business can spend beyond its bank balance"], marks: 2, hint: "Spending beyond your bank balance — short-term and flexible" },
    { question: "What is 'outsourcing'?", answer: "Outsourcing is when a business contracts an external company to perform a function that could be done in-house (e.g. payroll, IT support, cleaning, logistics). It reduces costs and allows the business to focus on core activities.", acceptedAnswers: ["hiring an external company to perform tasks instead of doing them in-house", "contracting out business functions to an outside provider", "outsourcing = external provider performs a business function, e.g. IT or payroll", "paying another business to carry out activities such as cleaning or payroll processing"], marks: 2, hint: "Paying an external company to do work you could do yourself" },
    { question: "What is 'Porter's Five Forces'?", answer: "Porter's Five Forces is a framework for analysing competitive intensity: 1. Competitive rivalry; 2. Threat of new entrants; 3. Threat of substitutes; 4. Buyer bargaining power; 5. Supplier bargaining power.", acceptedAnswers: ["five forces: competitive rivalry, threat of new entrants, substitutes, buyer power, supplier power", "Porter's Five Forces: competitive rivalry, new entrants, substitutes, buyer power, supplier power", "framework with five competitive forces: rivalry, entrants, substitutes, buyers, suppliers", "Porter: 1 rivalry 2 new entrants 3 substitutes 4 buyer power 5 supplier power"], marks: 2, hint: "Five forces that shape competition in an industry" },
    { question: "What is 'e-commerce'?", answer: "E-commerce is buying and selling goods or services online. It allows businesses to operate 24/7 globally, reach wider markets, and reduce overheads compared to physical stores. Examples: Amazon, ASOS, eBay.", acceptedAnswers: ["buying and selling goods or services online", "e-commerce = trading goods and services via the internet", "online buying and selling, operating 24/7 and reaching global markets", "commercial transactions conducted electronically over the internet"], marks: 1, hint: "Commerce conducted online" },
    { question: "What is the difference between 'offshoring' and 'outsourcing'?", answer: "Outsourcing contracts a function to an external company. Offshoring moves operations to another country. A business can offshore without outsourcing (opening its own factory abroad) or outsource without offshoring (using a domestic supplier).", acceptedAnswers: ["outsourcing = giving tasks to external company; offshoring = moving operations to another country", "offshoring moves work overseas; outsourcing contracts it to an external firm", "outsourcing = use external provider; offshoring = relocate to another country — can overlap", "offshoring: location change (abroad); outsourcing: ownership change (external company)"], marks: 2, hint: "One is about location (abroad), one is about who does it (external)" },
    { question: "What are 'multinational corporations' (MNCs)?", answer: "Multinational corporations are large businesses operating in multiple countries. Examples: Apple, Unilever, Shell. They benefit host countries through jobs and investment but may exploit lower wages and tax regulations.", acceptedAnswers: ["businesses that operate in more than one country", "MNCs operate across multiple countries; examples: Apple, Unilever, Shell", "large companies with operations in many countries — bring jobs but may exploit regulations", "multinationals: firms with production and sales across several countries"], marks: 2, hint: "Large businesses that operate across national borders" },
    { question: "What is 'Corporate Social Responsibility' (CSR)?", answer: "CSR is the practice of businesses taking responsibility for the social, ethical and environmental impact of their activities — beyond legal requirements. This may include charitable giving, ethical sourcing, carbon reduction targets, and community investment.", acceptedAnswers: ["businesses taking responsibility for their social, ethical and environmental impact", "CSR = voluntary actions businesses take to benefit society and the environment", "going beyond legal requirements to act ethically toward society and environment", "taking responsibility for social and environmental impacts, not just profit"], marks: 2, hint: "Voluntary actions to benefit society beyond legal requirements" },
    { question: "What is 'inflation' and how does it affect a business?", answer: "Inflation is a sustained rise in the general price level. For businesses: raw material costs rise (higher variable costs); wages may need to rise to maintain real pay; consumers' purchasing power falls (reducing demand); interest rates may rise to control inflation.", acceptedAnswers: ["general rise in prices; increases costs and may reduce consumer demand", "inflation raises costs (materials, wages) and can reduce consumer spending power", "sustained price level rise; increases production costs; may reduce demand", "rising prices that increase business costs and reduce consumer purchasing power"], marks: 2, hint: "Prices rising generally — how does this hurt a business?" },
    { question: "What is meant by 'market share'?", answer: "Market share is a business's sales as a percentage of total market sales. Formula: (Business's Sales ÷ Total Market Sales) × 100. A business with high market share has more pricing power and brand recognition.", acceptedAnswers: ["a business's sales as a percentage of total market sales", "market share = (firm's sales / total market sales) × 100", "the proportion of total market sales captured by one business", "percentage of total industry sales belonging to a specific business"], marks: 2, hint: "Your sales as a proportion of the whole market's sales" },
    { question: "What is a 'balance sheet'?", answer: "A balance sheet is a financial statement showing a business's assets (what it owns), liabilities (what it owes), and the difference (net assets / equity) at a specific date. Assets = Liabilities + Owner's Equity.", acceptedAnswers: ["snapshot of assets, liabilities and equity at a specific date", "balance sheet shows what a business owns (assets) and owes (liabilities) on a specific date", "financial statement: assets − liabilities = net assets (owner's equity)", "shows assets, liabilities, and capital at a point in time"], marks: 2, hint: "A financial snapshot of what the business owns and owes" },
    { question: "What is 'lean production'?", answer: "Lean production aims to minimise waste (time, materials, effort) in the production process without reducing quality or output. Techniques include just-in-time (JIT), kaizen (continuous improvement), and cell manufacturing.", acceptedAnswers: ["minimising waste in production without reducing quality", "lean production: remove all waste (time, materials, effort) from the process", "approach that eliminates waste using JIT, kaizen, and cell manufacturing", "production system focused on waste elimination and efficiency improvement"], marks: 2, hint: "Cutting all waste from the production process" },
    { question: "What is 'kaizen'?", answer: "Kaizen is a Japanese concept meaning 'continuous improvement'. Workers at all levels are encouraged to suggest small, incremental improvements to processes. It is a key element of lean production.", acceptedAnswers: ["continuous improvement involving all workers suggesting small incremental changes", "kaizen = continuous improvement; workers suggest and implement small improvements", "Japanese philosophy of constant small improvements to processes", "ongoing small improvements by all employees — key to lean production"], marks: 2, hint: "Japanese philosophy: small continuous improvements by everyone" },
    { question: "What does 'supply chain' mean?", answer: "The supply chain is the network of organisations involved in getting a product from raw materials to the end customer: suppliers → manufacturers → distributors → retailers → consumers.", acceptedAnswers: ["the network from raw materials to final customer: suppliers, manufacturers, distributors, retailers", "supply chain = all stages from raw material to end consumer", "suppliers → manufacturers → distributors → retailers → consumers", "the chain of businesses involved in producing and delivering a product"], marks: 2, hint: "The whole journey from raw materials to the end customer" },
    { question: "State two ways a business can use digital marketing.", answer: "Any two: search engine optimisation (SEO — improving Google ranking); pay-per-click advertising (Google Ads); social media marketing (Instagram, TikTok, Facebook); email marketing campaigns; influencer marketing; content marketing (blogs, videos).", acceptedAnswers: ["SEO and social media marketing", "email marketing and pay-per-click advertising", "influencer marketing and SEO", "social media and email marketing campaigns"], marks: 2, hint: "Online methods of reaching and engaging customers" },
    { question: "What is the difference between 'quantitative' and 'qualitative' market research?", answer: "Quantitative research collects numerical data (surveys with closed questions, sales statistics — gives measurable results). Qualitative research collects opinions and insights (focus groups, in-depth interviews — gives deeper understanding of why customers think/behave as they do).", acceptedAnswers: ["quantitative = numerical data; qualitative = opinions and insights", "quantitative: numbers and statistics; qualitative: opinions and reasons", "quantitative gives measurable data; qualitative gives deeper understanding of attitudes", "quant = closed survey data; qual = focus groups and interviews explaining why"], marks: 2, hint: "One is numbers, one is opinions and understanding" },
    { question: "What are 'interest rates' and how do they affect business borrowing?", answer: "Interest rates are the cost of borrowing money (or return on saving), set by the Bank of England's base rate. Rising interest rates increase the cost of loans and overdrafts — raising business costs. Falling rates make borrowing cheaper, encouraging investment.", acceptedAnswers: ["cost of borrowing; rising rates increase loan repayments, raising business costs", "interest rates determine how much borrowing costs; higher rates reduce investment", "Bank of England sets base rate; higher rates make loans more expensive for businesses", "rising interest rates increase fixed costs by raising loan repayments"], marks: 2, hint: "Cost of borrowing money — how does rising cost affect a business?" },
    { question: "What is 'automation' and how does it affect businesses?", answer: "Automation uses machines, robots or software to perform tasks previously done by humans. Benefits: consistent quality, lower long-term labour costs, higher output. Drawbacks: high upfront investment, job losses, inflexibility.", acceptedAnswers: ["using machines or software to replace human labour in tasks", "automation: machines perform tasks automatically; reduces labour costs but increases capital costs", "technology replacing human labour; benefits include consistency and lower costs; drawback is job losses", "robots or software performing production tasks — lowers labour costs but may displace workers"], marks: 2, hint: "Machines doing what humans used to do" },
  ],
  mid: [
    { question: "Explain the marketing mix (4 Ps) and how a business might use it when launching a new product.", answer: "Product: design, quality, features, branding — must meet customer needs. Price: strategy such as penetration (low to gain share), premium (high to signal quality), or competitive (match rivals). Place: distribution channels — online, retail, direct to consumer, wholesalers. Promotion: advertising, social media, PR, sales promotions. All four Ps must be aligned for success. A premium chocolate brand would use distinctive packaging (Product), premium pricing (Price), specialist retailers (Place), and aspirational advertising (Promotion) targeting affluent customers.", acceptedAnswers: ["Product, Price, Place, Promotion — the 4 Ps must be aligned", "product (design/quality), price (strategy), place (distribution), promotion (advertising)", "4 Ps: product features, pricing strategy, distribution channels, promotional methods", "marketing mix = product, price, place, promotion applied consistently to a target market"], marks: 4, hint: "Define all four Ps with a specific example for each, then explain how they should be aligned" },
    { question: "Explain the difference between fixed costs, variable costs, and total costs, with examples.", answer: "Fixed costs remain constant regardless of output — e.g. rent £2,000/month, equipment leases, insurance. Variable costs rise with output — e.g. raw materials, packaging, hourly wages. Total costs = Fixed Costs + Variable Costs. Example: a bakery with £2,000 fixed costs and £1 variable cost per loaf produces 3,000 loaves → total cost = £5,000. Understanding this allows break-even analysis: break-even = fixed costs ÷ contribution per unit.", acceptedAnswers: ["fixed (e.g. rent) + variable (e.g. materials) = total costs", "fixed costs stay same; variable costs change with output; total = fixed + variable", "total costs = fixed costs + variable costs; fixed = rent; variable = raw materials", "fixed don't change with output; variable do; total = fixed + variable"], marks: 4, hint: "Define each type with a specific example, then show how they combine" },
    { question: "Explain why a business might use motivation theories to improve performance.", answer: "Motivated employees produce higher quality work, reduce absenteeism and turnover. Maslow's Hierarchy identifies five needs: physiological (pay), safety (job security), social (teamwork), esteem (recognition), self-actualisation (development). Businesses must satisfy lower needs before higher ones motivate. Herzberg identified hygiene factors (pay, conditions — prevent dissatisfaction) and motivators (achievement, responsibility, progression — drive satisfaction). Taylor advocated financial incentives (piece-rate pay). A business might offer competitive salaries + recognition schemes + promotion paths to motivate across all levels.", acceptedAnswers: ["Maslow's hierarchy and Herzberg's two-factor theory explain what motivates employees", "motivated employees work harder; Maslow: 5 needs; Herzberg: hygiene factors vs motivators", "use Maslow and Herzberg to understand employee needs and improve engagement", "theories like Maslow and Herzberg help businesses design effective reward and recognition schemes"], marks: 4, hint: "Name at least two theorists, explain their theories, apply to a real business context" },
    { question: "Explain how a business can use market segmentation to improve marketing effectiveness.", answer: "Market segmentation divides a market into groups of customers with similar characteristics: demographic (age, gender, income), geographic (location), psychographic (lifestyle, values), behavioural (usage rate, brand loyalty). By targeting specific segments, a business can tailor its product, pricing, promotion and distribution to better meet customer needs. A sports clothing brand might target 18–30 active professionals with premium products on Instagram, while targeting budget-conscious teenagers with lower-priced ranges via TikTok. This improves conversion rates and reduces wasted advertising spend compared to mass marketing.", acceptedAnswers: ["segmenting by demographic, geographic, psychographic or behavioural characteristics", "divide market into groups and tailor the marketing mix to each group", "segmentation allows targeted marketing reducing wasted spend", "segment by age/income/lifestyle; tailor product, price, promotion to each segment"], marks: 4, hint: "Define segmentation, name 2-3 types, then apply to a specific example showing benefit" },
    { question: "Describe two methods a business could use to improve cash flow in the short term.", answer: "1. Negotiating extended credit from suppliers — paying in 60 days instead of 30 days keeps cash in the business longer, reducing the risk of a cash flow shortfall. 2. Offering discounts for early payment from customers — incentivises debtors to pay sooner, converting receivables to cash faster. Other valid: arranging a bank overdraft (short-term borrowing buffer), sale and leaseback of assets, reducing inventory levels, chasing outstanding debts, cutting unnecessary expenditure.", acceptedAnswers: ["extend supplier credit and offer early payment discounts to customers", "negotiate longer payment terms with suppliers; chase debtors to pay sooner", "reduce debtor days and extend creditor days", "two from: overdraft, reduce stock, early payment discounts, extended supplier credit, chasing debtors"], marks: 4, hint: "Two distinct methods — one about money coming in, one about money going out" },
    { question: "Explain the advantages and disadvantages of a business becoming a Public Limited Company (PLC).", answer: "Advantages: Can sell shares on the stock exchange, raising large amounts of capital for expansion. Limited liability protects shareholders. Enhanced profile and credibility. Easier to attract institutional investors. Disadvantages: Legal and administrative costs of flotation are high. Must publish detailed annual accounts — loss of confidentiality. Subject to shareholder pressure for short-term returns, limiting long-term investment. Risk of hostile takeover if share price falls. Directors may lose control if they hold less than 50% of shares.", acceptedAnswers: ["advantages: raise capital, limited liability; disadvantages: high costs, loss of control, public scrutiny", "PLC can sell shares raising capital but faces regulatory costs and shareholder pressure", "pros: capital from share issue; cons: flotation costs, loss of privacy, takeover risk", "benefits: limited liability, capital raising; drawbacks: public accounts, shareholder demands, takeover risk"], marks: 4, hint: "Balance advantages (capital, profile) against disadvantages (costs, scrutiny, loss of control)" },
    { question: "Explain what is meant by 'break-even' and how a business might use break-even analysis.", answer: "Break-even is the level of output where total revenue equals total costs — no profit or loss is made. Formula: Break-even = Fixed Costs ÷ (Selling Price − Variable Cost per unit). The denominator is the contribution per unit. Margin of safety = actual sales − break-even. Uses: setting minimum sales targets; assessing the impact of price or cost changes; informing decisions about new products; presenting to lenders/investors. Limitation: assumes constant selling price and linear cost relationships, which may not hold in practice.", acceptedAnswers: ["break-even = fixed costs ÷ (selling price − variable cost); where revenue = total costs", "break-even point is where total revenue equals total costs; no profit or loss", "formula: break-even = fixed costs ÷ contribution per unit", "output level at which a business covers all its costs exactly"], marks: 4, hint: "Give the formula, explain contribution, and describe at least two business uses" },
    { question: "Explain how technology is changing business operations and marketing.", answer: "Operations: automation reduces labour costs and improves consistency (robotics in manufacturing). E-commerce allows 24/7 global sales. Cloud computing reduces IT infrastructure costs. Big data analytics improve demand forecasting. Supply chain management software improves efficiency. Marketing: social media enables targeted, cost-effective marketing. Data analytics allows personalised advertising. SEO and pay-per-click advertising. Influencer marketing reaches specific audiences. Mobile apps improve customer engagement. Chatbots provide instant customer service. Overall: technology lowers barriers to entry for small businesses but creates competitive pressure from digital-native rivals.", acceptedAnswers: ["automation, e-commerce, data analytics improve operations; social media and targeted ads change marketing", "technology changes: automation in operations; digital/social media marketing", "operations: automation, cloud computing; marketing: social media, data analytics, personalisation", "e-commerce and automation for operations; social media and SEO for marketing"], marks: 4, hint: "Cover both operations AND marketing — give specific technologies and their business impact" },
    { question: "Explain the role of Human Resources (HR) in a business.", answer: "HR manages the workforce through the employee lifecycle. Recruitment and selection: writing job descriptions, advertising, interviewing, shortlisting. Training and development: induction, on-the-job/off-the-job training, upskilling. Performance management: appraisals, setting targets, identifying development needs. Employee relations: managing contracts, handling grievances and disciplinaries, ensuring legal compliance (employment law, equality, health and safety). Workforce planning: forecasting staffing needs, managing redundancies. Motivation and retention: designing reward packages, flexible working, career development pathways.", acceptedAnswers: ["HR handles recruitment, training, performance management, and employee relations", "HR recruits staff, trains them, manages performance and ensures legal compliance", "human resources: recruitment, training, appraisals, employee relations, workforce planning", "HR manages the employee lifecycle from recruitment to development and retention"], marks: 4, hint: "Cover recruitment, training, performance management, and legal compliance — with specific examples" },
    { question: "Explain two ethical issues a business might face and how it might respond to them.", answer: "1. Supply chain ethics: sourcing materials from suppliers that use poor working conditions or child labour. Response: conduct supplier audits, sign up to ethical trade initiatives (Fairtrade, ETI), publish supply chain transparency reports. Example: Nike revised supply chain practices following 1990s sweatshop controversy. 2. Environmental impact: production processes causing pollution or excessive carbon emissions. Response: invest in renewable energy, set net-zero targets, redesign packaging to reduce plastic waste, adopt circular economy principles. Businesses that proactively address ethics often benefit commercially through improved brand reputation and customer loyalty.", acceptedAnswers: ["supply chain exploitation and environmental damage; respond with audits and sustainability commitments", "ethical issues: poor supplier conditions and environmental harm; respond with fair trade and green policies", "e.g. supply chain ethics and environmental impact; respond with audits and sustainability targets", "two ethical issues (e.g. labour standards, pollution) and how business responds to each"], marks: 4, hint: "Name two specific ethical issues with real or realistic examples, and explain the business response to each" },
    { question: "Explain the advantages and disadvantages of franchising for the franchisee.", answer: "Advantages: operates under an established brand with proven products, reducing risk of failure. Franchisor provides training, marketing support, and a tested business model. Access to bulk purchasing power through the franchise network. Easier to secure finance (banks view franchises as lower risk). Disadvantages: franchise fee and ongoing royalties reduce profit. Franchisee has limited freedom to make decisions — must follow franchisor's rules. Success depends partially on the franchisor's reputation (one bad franchisee damages all). If the franchisor fails or changes terms, the franchisee is exposed.", acceptedAnswers: ["advantages: established brand, lower risk, training support; disadvantages: fees, limited freedom, dependent on franchisor", "franchisee benefits from established brand and support but pays fees and has less control", "pros: proven model, brand recognition; cons: royalties, restricted decisions, reputational risk from franchisor", "advantages = reduced risk, support; disadvantages = fees, limited independence"], marks: 4, hint: "Cover advantages (brand, support, lower risk) and disadvantages (fees, limited control, reliance on franchisor)" },
    { question: "Explain how a business might respond to a threat from a new competitor entering its market.", answer: "Businesses can respond in several ways: Price reduction: temporarily lower prices to make it harder for the entrant to compete. Increase advertising: reinforce brand loyalty among existing customers. Product differentiation: invest in new features or quality improvements to justify premium pricing. Loyalty schemes: reward existing customers to increase switching costs. Legal action: challenge any intellectual property infringement. Build barriers to entry: scale advantages, exclusive supply deals. Evaluation: aggressive price wars can damage profitability for both parties; building genuine differentiation is a more sustainable long-term response.", acceptedAnswers: ["lower prices, increase advertising, improve product, implement loyalty scheme", "respond with price cuts, stronger branding, product improvements, and customer loyalty programmes", "strategies: price competition, advertising, differentiation, loyalty schemes, scale advantages", "reduce prices, reinforce brand loyalty, improve product differentiation, use legal protection if applicable"], marks: 4, hint: "Cover at least three strategic responses — price, promotion, product, and customer loyalty" },
    { question: "Explain how changes in the economic cycle affect a business.", answer: "The economic cycle has four phases: boom (high growth), recession (two quarters of falling GDP), recovery, and depression. Boom: consumer confidence high, spending increases, businesses invest and hire. Recession: consumer spending falls, businesses cut costs, some may face closure. Recovery: spending gradually returns; businesses cautiously invest. Businesses that sell inferior goods (supermarket own-brand) may actually benefit during recession; luxury goods suffer most. Strategies: diversify product range; build cash reserves during boom; develop flexible cost structures (more variable, fewer fixed costs) to weather downturns.", acceptedAnswers: ["boom: high demand, growth; recession: falling demand, cost cutting; recovery: gradual improvement", "economic cycle: boom, recession, recovery — boom increases sales; recession reduces demand", "recession reduces consumer spending; boom increases demand; businesses must adapt strategies to each phase", "different phases affect demand: boom = growth; recession = falling sales; recovery = improving demand"], marks: 4, hint: "Cover at least two phases of the cycle and how they specifically impact demand, costs, and strategy" },
    { question: "Explain what is meant by 'stakeholder conflict' and give two examples.", answer: "Stakeholder conflict occurs when different stakeholders have opposing interests. Example 1: Shareholders want cost cuts to maximise dividends; employees want higher wages — a pay rise reduces profit, conflicting with shareholder interests. Example 2: The local community wants a factory to reduce pollution (higher cost); shareholders want lower costs to maximise profit. Businesses manage conflict through stakeholder mapping, CSR strategies, transparent communication, and finding compromise positions (e.g. phased wage increases, phased environmental investment).", acceptedAnswers: ["shareholders vs employees (profit vs wages); shareholders vs community (profit vs environment)", "conflict when stakeholders have opposing goals; e.g. shareholders want cuts but workers want higher pay", "example: shareholders want profit maximisation; employees want pay rises — conflicting goals", "two examples: shareholders vs employees (profit vs wages); business vs community (growth vs environment)"], marks: 4, hint: "Define conflict, then give two real examples with specific opposing interests" },
    { question: "Explain the role of the product life cycle in marketing decisions.", answer: "At each stage, businesses adapt their marketing mix: Introduction — heavy promotional spend to build awareness; often penetration pricing to attract early adopters. Growth — increase distribution; maintain promotion to sustain momentum; profits start to rise. Maturity — competitive pressure intense; may need to differentiate or extend the product life (new variants, packaging); focus on brand loyalty. Decline — consider extension strategies (new markets, new uses), reduce promotion costs, or withdraw. A business like Apple uses product versioning (iPhone 15, 16…) to continually re-enter the growth phase rather than reaching decline.", acceptedAnswers: ["at each stage (introduction, growth, maturity, decline) the marketing mix changes", "introduction: high promotion, penetration price; maturity: differentiation; decline: extension or withdrawal", "product life cycle informs pricing, promotion and distribution decisions at each stage", "introduction needs heavy promotion; maturity needs differentiation; decline needs extension strategy or withdrawal"], marks: 4, hint: "Describe the marketing mix decisions appropriate to at least three stages" },
    { question: "Explain how a rise in exchange rates affects a business that imports raw materials.", answer: "A rise (appreciation) in sterling means the pound buys more foreign currency. For an importer of raw materials, this is beneficial: the same amount of pounds buys more foreign goods, reducing import costs. This lowers variable costs, potentially improving profit margins. However, if the business also exports finished goods, the stronger pound makes its exports more expensive for overseas buyers, potentially reducing export sales — an offsetting negative. Overall the net effect on profit depends on the balance between imports and exports in the business's supply chain and revenue.", acceptedAnswers: ["stronger pound makes imports cheaper — reduces input costs for importers", "appreciation of sterling lowers import costs but raises export prices", "rising exchange rate benefits importers (cheaper materials) but hurts exporters (more expensive goods abroad)", "pound appreciation: imports cost less in pounds; good for businesses buying materials from abroad"], marks: 4, hint: "Think about the cost of imports in pounds when sterling strengthens" },
    { question: "Explain two advantages and two disadvantages of a business relocating abroad (offshoring).", answer: "Advantages: 1. Lower labour costs — wages in developing countries may be a fraction of UK wages, substantially reducing variable costs. 2. Proximity to new markets — locating production in a high-growth market reduces delivery times and tariffs, improving competitiveness. Disadvantages: 1. Quality control is harder to manage from a distance — language barriers and cultural differences complicate communication, risking inconsistent product standards. 2. Reputational risk — if poor working conditions in the overseas location become public, consumer backlash can damage the brand. (Nike's 1990s controversy is a real example.)", acceptedAnswers: ["advantages: lower labour costs, access to new markets; disadvantages: quality control issues, reputational risk", "offshoring benefits: cheaper labour, market access; drawbacks: quality control, PR/reputation risks", "lower wages abroad (advantage); harder to monitor quality (disadvantage); near new markets (advantage); ethical reputation risk (disadvantage)", "two advantages: cost savings, market proximity; two disadvantages: quality control and reputational risk"], marks: 4, hint: "Two genuine advantages (cost, markets) and two disadvantages (quality, reputation) with explanation" },
    { question: "Explain how a business might try to improve its net profit margin.", answer: "Net profit margin = Net Profit ÷ Revenue × 100. To improve it, a business can: (1) Reduce costs — renegotiate supplier contracts, improve operational efficiency, reduce waste (lean production), automate processes. (2) Increase revenue — raise prices (if demand is price-inelastic), grow sales volume through marketing, launch higher-margin products. (3) Both simultaneously — small improvements across many cost lines combined with modest revenue growth compound significantly. Evaluation: cutting costs risks quality or staff morale; raising prices risks losing sales if demand is price-elastic.", acceptedAnswers: ["reduce costs (e.g. renegotiate suppliers, lean production) or increase revenue (e.g. price rise, volume growth)", "improve NPM by cutting costs and/or increasing revenue", "net profit margin = net profit / revenue × 100; improve by reducing expenses or growing revenue", "reduce operating costs and/or raise revenue to improve net profit margin"], marks: 4, hint: "Net profit margin = net profit / revenue × 100 — what affects each element?" },
    { question: "Explain what is meant by 'price elasticity of demand' and why it matters when setting prices.", answer: "Price elasticity of demand (PED) measures how sensitive demand is to a price change. PED = % change in quantity demanded ÷ % change in price. Elastic demand (PED > 1): demand changes more than the price — raising price reduces total revenue (e.g. supermarket own-brands). Inelastic demand (PED < 1): demand changes less than the price — raising price increases total revenue (e.g. petrol, essential medicines). Businesses with inelastic demand can use price skimming profitably; those with elastic demand should focus on penetration pricing to grow volume.", acceptedAnswers: ["PED measures how responsive demand is to price changes; elastic = demand very sensitive; inelastic = demand less sensitive", "PED = % change in demand / % change in price; elastic demand means price rises lose sales; inelastic means price rises increase revenue", "price elasticity shows how demand changes with price; if inelastic, can raise prices profitably", "elastic: demand falls a lot when price rises; inelastic: demand barely changes — informs pricing strategy"], marks: 4, hint: "Define PED, distinguish elastic from inelastic, and explain the pricing implication of each" },
    { question: "Explain how a business can use the Boston Matrix to manage its product portfolio.", answer: "The Boston Matrix plots products by market share and market growth rate. Stars (high share, high growth): require investment to maintain position but generate good returns — priority products. Cash Cows (high share, low growth): generate strong cash flow with low investment; fund Stars and Question Marks. Question Marks (low share, high growth): uncertain future; business must decide whether to invest and turn into Stars, or divest. Dogs (low share, low growth): little potential; usually withdrawn unless they serve a strategic niche. A balanced portfolio includes cash cows to fund growth, stars to drive future revenue, and carefully selected question marks as future stars.", acceptedAnswers: ["Boston Matrix: stars need investment; cash cows fund growth; question marks need decision (invest or divest); dogs are withdrawn", "use the matrix to balance portfolio: cash cows fund stars; question marks selectively invested in; dogs discontinued", "stars: invest; cash cows: use cash generated; question marks: invest or divest; dogs: withdraw", "four quadrants inform product investment and divestment decisions"], marks: 4, hint: "Describe what strategy applies to each quadrant and how the matrix informs portfolio decisions" },
  ],
  long: [
    { question: "A small café is considering expanding by opening a second location. Assess the risks and opportunities of this decision. (9 marks)", answer: "Opportunities: Increased revenue and profit from a second site. Building brand recognition — reputation spreads across a wider geographic area. Economies of scale — bulk purchasing of ingredients and shared marketing costs reduce average unit costs. Ability to serve more customers and attract different market segments. Platform for further expansion if successful. Risks: High start-up costs (lease, fit-out, equipment) may cause cash flow problems — especially if the second site takes time to reach break-even. Management stretched thinner — maintaining quality and consistency across two sites is harder. Brand damage if second site underperforms. New location demographics may differ — requires thorough market research. Increased borrowing raises fixed cost base, raising break-even. Financial assessment: Projected revenue must exceed total costs at the second site. Funding options: bank loan (increases debt and interest costs), retained profit (no debt but reduces reserves), external investor (dilutes ownership). Recommendation: Viable if the original café has proven consistent profitability, replicable systems, and sufficient capital or credit to fund expansion without jeopardising cash flow. A pop-up or catering service in the new area first would reduce risk by testing demand before committing to a long lease.", acceptedAnswers: ["opportunities: revenue growth, economies of scale; risks: cash flow, management stretch, brand risk", "expansion offers growth and scale but risks cash flow problems and quality consistency", "assess: more revenue and brand growth vs high start-up costs and management challenges", "benefits: more customers, economies of scale; risks: cash flow, quality control, market fit"], marks: 9, hint: "Cover specific opportunities AND risks. Include financial considerations (break-even, funding). Give a justified recommendation." },
    { question: "Evaluate whether a business should prioritise CSR (corporate social responsibility) over profit maximisation. (9 marks)", answer: "Arguments for prioritising profit: Shareholders invest for financial return — legal duty to maximise shareholder value (Friedman's view). Profit enables investment, job creation, and innovation. Without profit, the business cannot survive long enough to pursue any other goals. Competitive markets force focus on profit to remain viable. Arguments for CSR: Stakeholder theory (Freeman) — responsibilities extend beyond shareholders to employees, communities, environment. Long-term profitability depends on social licence to operate. Consumer behaviour increasingly influenced by ethical reputation — Unilever's sustainable brands grew 46% faster than the rest of the portfolio. Examples: Patagonia's 1% for the Planet, Ben & Jerry's social activism show CSR and profit are compatible. Triple bottom line: People, Planet, Profit. Counter: CSR can be 'greenwashing' — superficial gestures without fundamental change. Evaluation: The dichotomy is false — the most successful modern businesses integrate social responsibility into their model. Porter and Kramer's 'shared value' argues that creating value for society also creates value for the business. Conclusion: Businesses should not sacrifice long-term viability for short-term profits, nor ignore profitability for altruistic goals. The optimal position is integrating CSR into core strategy so social value and commercial value reinforce each other.", acceptedAnswers: ["CSR and profit are not mutually exclusive; shared value approach integrates both", "Friedman argues profit first; Freeman's stakeholder theory supports CSR; best approach balances both", "CSR improves reputation and long-term profit; pure profit maximisation may damage stakeholder relations", "evaluate Friedman vs Freeman; conclude CSR and profit can be complementary via shared value"], marks: 9, hint: "Use named theorists (Friedman, Freeman, Porter). Give real examples. Reach a justified, nuanced conclusion." },
    { question: "Analyse the impact of a rise in interest rates on a small manufacturing business. (8 marks)", answer: "A rise in interest rates affects the business in several ways. Borrowing costs: if the business has variable-rate loans or an overdraft, interest repayments increase, raising fixed costs and reducing profit. It may delay investment in new equipment. Consumer demand: higher mortgage repayments reduce consumers' disposable income, reducing demand for discretionary goods — the business may see falling sales. Exchange rate: higher UK rates attract foreign investment, strengthening sterling. This makes the business's exports more expensive for overseas buyers (potential loss of export sales) but makes imported raw materials cheaper, partially offsetting cost pressures. Supplier costs: supplier firms also face higher borrowing costs, which may feed through as higher input prices. Overall: the net effect is likely negative for most small manufacturers — higher costs, reduced demand, squeezed profit margins. Mitigation strategies: fix interest rates on loans, hedge exchange rate risk, focus on domestic market, explore cost reduction. Evaluation: the severity depends on the business's debt level and what proportion of revenue comes from exports.", acceptedAnswers: ["higher rates increase borrowing costs, reduce consumer demand, and strengthen sterling", "interest rate rise: increases loan costs, reduces consumer spending, strengthens pound affecting exports", "higher borrowing costs, lower demand, exchange rate effects — mainly negative for small manufacturers", "rising interest rates raise business costs and reduce consumer disposable income"], marks: 8, hint: "Cover at least 3 distinct impacts: borrowing costs, consumer demand, exchange rates. Consider both negative and any positive effects. Evaluate severity." },
    { question: "Assess the importance of market research before launching a new product. (8 marks)", answer: "Market research informs critical launch decisions. Primary research (surveys, focus groups, product trials) directly tests consumer reactions — avoiding costly launches of products nobody wants. Secondary research (industry reports, competitor analysis) reveals market size, trends, and gap opportunities. Uses: identifying target market and customer needs; testing the concept, name, packaging; informing pricing decisions; assessing the competitive landscape; forecasting demand for production planning. Risks of skipping research: launching at wrong price point; missing unmet customer needs; underestimating competition; over- or under-producing. Limitations: research has costs — may be unaffordable for very small businesses. Primary research can be biased (respondents say what they think researchers want to hear). Markets change fast — research may be outdated by launch. Secondary data may be inaccurate. Evaluation: market research is most valuable for high-investment product launches where failure costs are high. For low-cost, fast-moving products in a well-understood market, the cost-benefit may not justify extensive research. However, even basic desk research (competitor websites, online reviews) carries minimal cost and meaningfully reduces risk.", acceptedAnswers: ["market research reduces risk by identifying customer needs before launch", "primary and secondary research inform pricing, target market and competitive analysis", "research identifies gaps, informs the marketing mix, and reduces launch failure risk", "market research vital for identifying customer needs but limited by cost and time"], marks: 8, hint: "Cover the types of research, specific uses before launch, limitations, and evaluate when it matters most" },
    { question: "Evaluate the advantages and disadvantages of a business using price skimming versus penetration pricing for a new product. (8 marks)", answer: "Price skimming sets a high initial price, then lowers it over time. Advantages: maximises revenue from early adopters willing to pay a premium (e.g. iPhone launch prices). Signals quality and exclusivity. Recovers development costs quickly. Allows gradual market expansion as price falls. Disadvantages: only works with inelastic demand and genuine innovation — easily copied products will see competitors quickly undercut. Small initial market. Risk of reputation damage if price drops appear unfair to early adopters. Penetration pricing sets a low initial price to gain market share rapidly. Advantages: builds customer base quickly; effective in competitive markets; may create high switching costs once customers are established. Disadvantages: low margins initially; may attract price-sensitive customers with low loyalty; difficult to raise prices later without losing customers (psychological resistance); may trigger price war. Evaluation: skimming is most appropriate for genuinely innovative products with few close substitutes and an identifiable early-adopter segment (tech products, pharmaceuticals). Penetration is most appropriate in price-sensitive, competitive markets where building scale quickly creates cost advantages (streaming services, budget airlines, new grocery entrants). The choice must align with the product's competitive position, cost structure, and target market.", acceptedAnswers: ["skimming: high initial price suits innovative products; penetration: low price to gain market share", "price skimming maximises early revenue; penetration builds market share quickly", "skimming suits premium/innovative products; penetration suits competitive price-sensitive markets", "evaluate both strategies: skimming = high price then lower; penetration = low price to enter market"], marks: 8, hint: "Define both strategies clearly, weigh advantages and disadvantages of each, then evaluate when each is appropriate with real examples" },
    { question: "A business is deciding whether to use automation in its production line. Evaluate the case for and against this investment. (9 marks)", answer: "Case for automation: Automation reduces long-run labour costs significantly — robots work 24/7 without wages, holiday pay, or sick leave. Consistency: machines produce to exact specifications every time, improving quality assurance. Increased output: automated lines can produce at higher speed and volume, enabling the business to meet growing demand. Competitive advantage: if rivals automate, failing to do so leaves the business at a cost disadvantage. Case against: High upfront capital cost — automation equipment can cost hundreds of thousands or millions of pounds. This may require significant borrowing, increasing fixed costs and raising break-even. Inflexibility: automated lines are often designed for specific products; adapting to market changes is costly. Job losses create ethical concerns, potential strikes, and negative publicity. Automation may not be appropriate for low-volume, highly customised production. Financial assessment: the investment should be evaluated using return on investment (ROI) and payback period analysis. If the annual saving in labour costs exceeds the annual cost of the investment, automation becomes financially justified. Conclusion: Automation is most compelling for high-volume, standardised production where labour costs are a major expense and quality consistency is critical. A phased approach (automating one line first) reduces financial risk. The business should also consider retraining displaced workers to mitigate reputational damage.", acceptedAnswers: ["for: lower costs, quality consistency, higher output; against: high capital cost, inflexibility, job losses", "automation reduces labour costs and improves quality but requires large investment and may cause redundancies", "evaluate: cost savings and consistency vs upfront investment and reduced flexibility", "benefits: 24/7 production, lower long-run costs; drawbacks: expensive, inflexible, job losses"], marks: 9, hint: "Build the case FOR automation (costs, quality, output), the case AGAINST (capital, inflexibility, job losses), then reach a justified conclusion using financial reasoning" },
  ],
  flashcard: [
    { term: "Break-Even Point", definition: "The level of output where total revenue equals total costs — neither profit nor loss. Formula: Fixed Costs ÷ (Selling Price − Variable Cost per unit). The denominator is contribution per unit.", example: "Fixed costs £1,000; selling price £5; variable cost £3 → break-even = 1000÷(5−3) = 500 units" },
    { term: "Margin of Safety", definition: "The difference between actual sales and the break-even point. Tells a business how much sales can fall before it starts making a loss. Margin of safety = Actual Sales − Break-Even Sales.", example: "If break-even is 500 units and actual sales are 700 units, margin of safety = 200 units" },
    { term: "Stakeholders", definition: "Any individual or group with an interest in the business. Internal: shareholders, employees, managers. External: customers, suppliers, government, local community. Different stakeholders have conflicting interests.", example: "Shareholders want high dividends; employees want higher wages — both increase costs, creating a conflict" },
    { term: "Economies of Scale", definition: "As output increases, average cost per unit falls. Purchasing (bulk discounts), managerial (specialists), financial (better loan rates), and technical (larger machinery) economies.", example: "A supermarket buys bread at a lower cost per loaf than a corner shop due to purchasing economies" },
    { term: "Limited Liability", definition: "Owners (shareholders) can only lose what they invested — personal assets are protected if the business fails. Applies to Ltd and PLC. Sole traders and partnerships have unlimited liability.", example: "A shareholder in Tesco can only lose their share investment, not their house" },
    { term: "Cash Flow Forecast", definition: "A financial document predicting monthly cash inflows and outflows over a future period. Identifies future cash shortfalls so a business can arrange finance in advance. Net cash flow = inflows − outflows.", example: "A startup forecasting low January sales can arrange an overdraft before cash runs out" },
    { term: "Profit and Loss Account", definition: "Financial statement showing revenue, costs, and profit/loss over a period. Gross Profit = Revenue − Cost of Sales. Net Profit = Gross Profit − Operating Expenses.", example: "Revenue £100,000 − CoS £60,000 = Gross Profit £40,000 − Expenses £25,000 = Net Profit £15,000" },
    { term: "Marketing Mix (4 Ps)", definition: "Product (design, quality, branding), Price (strategy: skimming, penetration, competitive), Place (distribution channels), Promotion (advertising, social media, PR). All four must be aligned to target market.", example: "Budget airline: standard product, low price, online-only booking, price-comparison website ads" },
    { term: "Market Segmentation", definition: "Dividing a market into groups with similar characteristics: demographic (age/income), geographic (location), psychographic (lifestyle), behavioural (usage rate). Allows targeted marketing.", example: "Nike segments by age, sport, and performance level — different products and messaging for each" },
    { term: "Sources of Finance", definition: "Internal: retained profit, owner's savings, selling assets. External short-term: overdraft, trade credit. External long-term: bank loan, share issue, mortgage, venture capital, crowdfunding.", example: "A startup might use owner's savings + crowdfunding; an established firm uses retained profit + bank loan" },
    { term: "Organisational Structure", definition: "The hierarchy within a business. Hierarchical (tall): many layers, narrow span of control, slow decisions. Flat: few layers, wide span, faster decisions. Matrix: cross-departmental teams. Affects communication and motivation.", example: "McDonald's has a hierarchical structure; a small tech startup typically has a flat structure" },
    { term: "Maslow's Hierarchy of Needs", definition: "Five levels of needs motivating employees: 1. Physiological (pay), 2. Safety (job security), 3. Social (teamwork), 4. Esteem (recognition), 5. Self-actualisation (fulfilling potential). Lower needs must be met first.", example: "If pay is inadequate (level 1 unmet), offering a promotion (level 5) will not motivate" },
    { term: "Herzberg's Two-Factor Theory", definition: "Hygiene factors (pay, working conditions, job security) prevent dissatisfaction but do not motivate. Motivators (achievement, recognition, responsibility, advancement) actually drive higher performance.", example: "Giving a pay rise prevents a complaint but does not motivate; giving more responsibility does" },
    { term: "Entrepreneur", definition: "A person who takes financial risk to start and run a business in exchange for potential profit. Key traits: risk-taking, innovation, leadership, resilience, financial awareness.", example: "James Dyson spent years developing the bagless vacuum before achieving commercial success" },
    { term: "Business Plan", definition: "A written document describing a business's objectives, strategies, target market, financial forecasts (cash flow, profit/loss), and operational plans. Used to secure finance and guide decision-making.", example: "A new restaurant uses a business plan to obtain a bank loan, showing projected revenue and costs" },
    { term: "Trade Unions", definition: "Organisations that represent workers' collective interests in negotiations with employers over pay, working conditions, and job security. Collective bargaining aims for better terms than individual negotiation.", example: "The RMT union negotiates rail workers' pay with Network Rail; industrial action (strikes) is a last resort" },
    { term: "Product Life Cycle", definition: "Four stages: Introduction (high costs, low sales, heavy promotion), Growth (rising sales, rising profit), Maturity (peak sales, heavy competition, differentiation needed), Decline (falling sales — extend or withdraw).", example: "DVDs are in decline; streaming services (Netflix) were in rapid growth phase after launch" },
    { term: "Boston Matrix", definition: "Portfolio analysis tool: Star (high share, high growth — invest), Cash Cow (high share, low growth — milk for cash), Question Mark (low share, high growth — invest or divest), Dog (low share, low growth — withdraw).", example: "iPhone = Star; old iPod = Dog; a new product line might be a Question Mark" },
    { term: "Contribution Per Unit", definition: "Selling Price − Variable Cost per unit. Shows how much each unit sold contributes to covering fixed costs and then generating profit once fixed costs are paid.", example: "Selling price £10, variable cost £6 → contribution = £4. Fixed costs £2,000 → break-even = 500 units" },
    { term: "Gross Profit Margin (GPM)", definition: "GPM = (Gross Profit ÷ Revenue) × 100. Shows what percentage of revenue remains after deducting cost of sales. Higher GPM = more efficient at generating profit from direct trading activities.", example: "Revenue £200,000; gross profit £80,000 → GPM = 40%. For every £1 of sales, 40p is gross profit." },
    { term: "Net Profit Margin (NPM)", definition: "NPM = (Net Profit ÷ Revenue) × 100. The final profit percentage after all costs (fixed and variable). Lower than GPM because it deducts overheads. Shows overall profitability efficiency.", example: "Gross profit £80,000 − overheads £50,000 = net profit £30,000 → NPM = 30,000/200,000 × 100 = 15%" },
    { term: "Porter's Five Forces", definition: "Framework for competitive analysis: 1. Competitive rivalry (intensity of existing competition), 2. Threat of new entrants (barriers to entry), 3. Threat of substitutes, 4. Buyer bargaining power, 5. Supplier bargaining power.", example: "Supermarkets: high rivalry (Tesco vs Sainsbury's vs Aldi); high buyer power (customers switch easily); high supplier power (few food producers)" },
    { term: "Just-In-Time (JIT)", definition: "Lean production approach: materials and stock ordered and delivered only when needed for production. Eliminates stock-holding costs but requires highly reliable suppliers and accurate demand forecasting.", example: "Toyota pioneered JIT — components arrive from suppliers hours before they are needed on the production line" },
    { term: "Price Elasticity of Demand", definition: "PED = % change in quantity demanded ÷ % change in price. Elastic (PED>1): demand sensitive to price — raising price loses revenue. Inelastic (PED<1): demand insensitive — raising price increases revenue.", example: "Petrol is price-inelastic (people need it regardless of price); luxury handbags are price-elastic" },
    { term: "Franchise", definition: "A business model where the franchisor licences its brand, systems, and products to a franchisee. Franchisee pays initial fee and ongoing royalties. Lower risk than starting from scratch but less independence.", example: "McDonald's: a franchisee buys the right to operate a McDonald's restaurant under strict brand standards" },
    { term: "Retained Profit", definition: "Profit kept within the business after tax and dividends, reinvested for growth or held as reserves. The cheapest source of internal finance — no interest costs or loss of ownership.", example: "Apple held hundreds of billions in retained profits, allowing it to fund R&D without borrowing" },
    { term: "Lean Production", definition: "Production approach minimising all forms of waste (time, materials, space, defects) without sacrificing quality. Techniques: JIT, kaizen (continuous improvement), cell manufacturing, 5S, kanban.", example: "Toyota Production System is the world's leading lean manufacturing model — waste elimination at every step" },
    { term: "CSR (Corporate Social Responsibility)", definition: "Voluntary actions beyond legal requirements addressing environmental, social, and ethical impacts. Can include sustainability targets, charitable giving, ethical sourcing, community investment.", example: "Patagonia donates 1% of sales to environmental causes; Ben & Jerry's sources Fairtrade ingredients" },
    { term: "Multinational Corporation (MNC)", definition: "A business with operations (production, sales, or offices) in multiple countries. Benefits from cheaper labour, local market access, and tax efficiencies. Examples: Apple, Unilever, Shell, Amazon.", example: "Apple designs in California, manufactures in China, and sells globally — a true MNC" },
    { term: "Exchange Rate", definition: "The price of one currency in terms of another. Appreciation (stronger pound): imports cheaper, exports more expensive — bad for exporters. Depreciation (weaker pound): exports cheaper, imports more expensive — good for exporters.", example: "If £1 = $1.30 and rises to £1 = $1.50, UK exports to the USA become more expensive — export demand falls" },
    { term: "The 4 Types of Market Research", definition: "Primary quantitative (surveys/questionnaires — numerical), Primary qualitative (focus groups/interviews — opinions), Secondary internal (sales records, customer data), Secondary external (government stats, trade reports).", example: "A startup does a 500-person survey (primary quantitative) + 3 focus groups (primary qualitative) before launch" },
  ],
};
